{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Rates & Commitments — {{BUSINESS_NAME}}</title>
  <meta name='description' content='Sustainable commitments, bespoke plans, clear pricing.'>
  <style>
    :root{--bg:#fbfbfb;--card:#fff;--muted:#6b6b6b;--accent:#5a9c7a;--accent-2:#6aa3c9;--glass: rgba(255,255,255,0.6);font-family:Inter,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial}
    *{box-sizing:border-box}
    html,body{height:100%}body{margin:0;background:linear-gradient(180deg,var(--bg),#f2f8f6);color:#122;line-height:1.45}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:46px;height:46px;border-radius:10px;background:var(--accent);display:grid;place-items:center;color:#fff;font-weight:700}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none;font-size:14px}
    .hero{padding:36px 28px;display:grid;grid-template-columns:1fr 380px;gap:28px;align-items:start}
    .lead{background:linear-gradient(135deg,rgba(255,255,255,0.7),rgba(250,255,250,0.6));padding:28px;border-radius:12px;box-shadow:0 6px 20px rgba(17,22,16,0.06)}
    h1{margin:0 0 8px 0;font-size:26px;color:#0f2b1e}
    p.lead-desc{margin:0;color:var(--muted)}
    .aside{padding:20px;border-radius:12px;background:var(--card);box-shadow:0 8px 30px rgba(12,18,14,0.06)}
    .tiers{display:flex;gap:14px;margin:20px 0}
    .tier{flex:1;padding:18px;border-radius:10px;background:var(--card);border:1px solid #e9efe9}
    .tier h3{margin:0 0 6px 0}
    .price{font-size:20px;color:var(--accent);font-weight:700}
    .features{margin-top:12px;font-size:14px;color:var(--muted)}
    .cta-row{display:flex;gap:12px;margin-top:14px}
    .btn{padding:10px 14px;border-radius:8px;border:0;cursor:pointer}
    .btn-primary{background:var(--accent);color:#fff}
    .btn-ghost{background:transparent;border:1px solid #dbeee0;color:var(--accent)}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
    footer{padding:28px;text-align:center;color:var(--muted);font-size:13px}

    /* Habit builder */
    .habit-widget{margin-top:16px;padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fcfffd);border:1px solid #eef7f1}
    .habit-controls{display:flex;gap:8px;flex-wrap:wrap}
    .input{padding:8px 10px;border-radius:8px;border:1px solid #e6efe8}
    .days{margin-top:12px}
    ul.checklist{list-style:none;padding:0;margin:0 0 8px 0}
    ul.checklist li{display:flex;align-items:center;gap:10px;padding:8px;border-radius:8px;border:1px dashed rgba(90,156,122,0.08);margin-bottom:8px;background:#fff}
    .print-area{display:none}

    /* pattern background */
    .pattern-wrap{position:absolute;inset:0;pointer-events:none;opacity:0.06}
    svg.pattern{width:100%;height:100%}

    @media(max-width:880px){.hero{grid-template-columns:1fr}.aside{order:2}}
  </style>
</head>
<body>
  <div class='pattern-wrap' aria-hidden='true'>
    <svg class='pattern' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'>
      <defs>
        <pattern id='p1' x='0' y='0' width='80' height='80' patternUnits='userSpaceOnUse'>
          <rect width='80' height='80' fill='none'/>
          <path d='M0 40 Q20 0 40 40 T80 40' fill='none' stroke='%236aa3c9' stroke-width='1' stroke-opacity='0.12'/>
          <circle cx='12' cy='12' r='2' fill='%235a9c7a' fill-opacity='0.18'/>
        </pattern>
      </defs>
      <rect width='100%' height='100%' fill='url(%23p1)' />
    </svg>
  </div>

  <header>
    <div class='brand'>
      <div class='logo'>W</div>
      <div>
        <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
        <div style='font-size:12px;color:var(--muted)'>small rhythms, steady momentum</div>
      </div>
    </div>
    <nav aria-label='Primary'>
      <a href='index.html'>Root</a>
      <a href='about.html'>Philosophy</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Journeys</a>
      <a href='pricing.html' style='font-weight:600;color:var(--accent)'>Rates</a>
      <a href='testimonials.html'>Voices</a>
      <a href='book.html'>Reserve</a>
      <a href='contact.html'>Reach</a>
    </nav>
  </header>

  <main>
    <section class='hero'>
      <div class='lead'>
        <h1>Clear commitments, crafted for your life</h1>
        <p class='lead-desc'>Choose how you want to cultivate change — short focus sprints, steady monthly practice, or a blended pathway with coaching check-ins and self-guided habits. Pricing is framed around the time you dedicate and the outcomes you track.</p>

        <div class='tiers'>
          <div class='tier'>
            <h3>Starter Sprint</h3>
            <div class='price'>$120 / 4 weeks</div>
            <div class='features'>Two coaching conversations + 4 micro-frameworks + habit checklist</div>
            <div class='cta-row'>
              <button class='btn btn-primary' onclick="location.href='book.html'">Begin the Sprint</button>
              <button class='btn btn-ghost' onclick="alert('Ask us about sliding scale options at {{EMAIL}}')">Ask about scale</button>
            </div>
          </div>
          <div class='tier'>
            <h3>Steady Course</h3>
            <div class='price'>$320 / 12 weeks</div>
            <div class='features'>Weekly session option + tailored habit builder + progress maps</div>
            <div class='cta-row'>
              <button class='btn btn-primary' onclick="location.href='book.html'">Enroll in Course</button>
              <button class='btn btn-ghost' onclick="alert('Details via {{EMAIL}}')">Request syllabus</button>
            </div>
          </div>
          <div class='tier'>
            <h3>Hybrid Pathway</h3>
            <div class='price'>$880 / 6 months</div>
            <div class='features'>Blended coaching + habit architecture + quarterly reflection sessions</div>
            <div class='cta-row'>
              <button class='btn btn-primary' onclick="location.href='book.html'">Design my Pathway</button>
              <button class='btn btn-ghost' onclick="alert('Call us: {{PHONE}}')">Talk with a guide</button>
            </div>
          </div>
        </div>

        <p class='note'>Payments may be split. Each commitment includes a bite-sized framework you can use independently. No medical advice here — we focus on daily habits, clarity, and sustainable routines.</p>
      </div>

      <aside class='aside'>
        <h4 style='margin:0 0 8px 0'>7-Day Challenge: build a tiny practice</h4>
        <p style='margin:0 0 12px 0;color:var(--muted)'>Create a 7-day checklist you can print or save — designed to cut friction and create forward motion.</p>

        <div class='habit-widget' id='habitWidget'>
          <div class='habit-controls'>
            <input class='input' id='habitName' placeholder='Habit to try (e.g., 10-min walk)'>
            <select id='habitIntensity' class='input' aria-label='Intensity'>
              <option value='light'>Light — daily nudge</option>
              <option value='steady' selected>Steady — daily anchor</option>
              <option value='bold'>Bold — stretch practice</option>
            </select>
            <button class='btn btn-primary' id='genChallenge'>Make checklist</button>
          </div>

          <div class='days' id='challengeContainer' aria-live='polite'></div>

          <div style='display:flex;gap:8px;margin-top:12px'>
            <button class='btn' id='printChallenge'>Print checklist</button>
            <button class='btn btn-ghost' id='downloadTxt'>Download text</button>
          </div>
        </div>

      </aside>
    </section>
  </main>

  <footer>
    <div>Questions? <a href='contact.html'>Reach out</a> — or call <strong>{{PHONE}}</strong></div>
    <div style='margin-top:6px'>&copy; <span id='year'></span> {{BUSINESS_NAME}}</div>
  </footer>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();

    // Habit builder logic
    function generateChallenge(name, intensity){
      if(!name) name = 'Daily practice';
      const base = {
        light: ['Minute intention','Short practice','Reflect briefly','Move gently','Breathe','Gratitude note','Mini tidy'],
        steady: ['Set intention (1m)','Core practice (10m)','Hydrate/Move','Note progress','Micro-reflection','Connect with someone','Reset for next day'],
        bold: ['Intent + planning','Focused practice (20m)','Stretch or walk','Journal (5m)','Share progress','Deep breathing','One new boundary']
      }[intensity || 'steady'];

      const days = base.map((task,i)=>({day:i+1,task: `${name}: ${task}`}));
      return days;
    }

    function renderChallenge(days){
      const c = document.getElementById('challengeContainer');
      c.innerHTML = '';
      const ul = document.createElement('ul'); ul.className='checklist';
      days.forEach(d=>{
        const li = document.createElement('li');
        const cb = document.createElement('input'); cb.type='checkbox'; cb.id='d'+d.day;
        const label = document.createElement('label'); label.setAttribute('for','d'+d.day); label.textContent = 'Day '+d.day+' — '+d.task;
        li.appendChild(cb); li.appendChild(label); ul.appendChild(li);
      });
      c.appendChild(ul);
    }

    document.getElementById('genChallenge').addEventListener('click', ()=>{
      const name = document.getElementById('habitName').value.trim();
      const intensity = document.getElementById('habitIntensity').value;
      const days = generateChallenge(name, intensity);
      renderChallenge(days);
    });

    document.getElementById('printChallenge').addEventListener('click', ()=>{
      const html = document.getElementById('challengeContainer').innerHTML || '<p style="color:#888">No challenge yet</p>';
      const win = window.open('', '_blank', 'width=600,height=800');
      win.document.write('<!doctype html><html><head><meta charset="utf-8"><title>7-Day Checklist</title></head><body style="font-family:Helvetica,Arial,sans-serif;padding:20px">');
      win.document.write('<h2>7-Day Checklist</h2>');
      win.document.write(html);
      win.document.write('<p style="font-size:12px;color:#666">Generated from {{BUSINESS_NAME}}</p>');
      win.document.write('</body></html>');
      win.document.close();
      win.print();
    });

    document.getElementById('downloadTxt').addEventListener('click', ()=>{
      const ul = document.querySelectorAll('#challengeContainer ul.checklist li label');
      if(!ul.length){ alert('Make a checklist first'); return; }
      let out = '7-Day Challenge from {{BUSINESS_NAME}}\n\n';
      ul.forEach((l,i)=>{ out += (i+1)+'. '+l.textContent+'\n'; });
      const blob = new Blob([out], {type: 'text/plain'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = '7-day-challenge.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
    });
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Voices — Stories & Notes</title>
  <style>
    :root{--bg:#fff;--muted:#6b6b6b;--accent:#5a9c7a;font-family:Inter,system-ui,Segoe UI,Roboto,Arial}
    body{margin:0;background:linear-gradient(180deg,#fbfff9,#f7fbf8);color:#102018}
    header{display:flex;justify-content:space-between;padding:18px 24px}
    .brand{display:flex;gap:12px;align-items:center}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    main{padding:24px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:22px}
    .card{background:#fff;border-radius:10px;padding:16px;box-shadow:0 8px 24px rgba(14,20,16,0.06)}
    .testimonial{margin-bottom:12px}
    .quote{font-style:italic;color:#264237;margin:0}
    .who{font-size:13px;color:var(--muted);margin-top:6px}
    .meta{display:flex;gap:8px;align-items:center;margin-top:10px}
    .rating{color:#f0b400}
    .cta{margin-top:12px}
    .btn{padding:8px 12px;border-radius:8px;border:0;cursor:pointer}
    .btn-primary{background:var(--accent);color:#fff}
    .micro{font-size:13px;color:var(--muted);margin-top:8px}

    /* small habit generator on this page too */
    .mini-habit{margin-top:12px;padding:12px;border-radius:8px;background:linear-gradient(180deg,#fff,#f9fffa);border:1px solid #eef8ee}
    .mini-habit input{padding:8px;border-radius:8px;border:1px solid #e7f0ea;width:100%}

    @media(max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class='brand'>
      <div style='width:44px;height:44px;background:var(--accent);border-radius:9px;display:grid;place-items:center;color:#fff;font-weight:700'>W</div>
      <div>
        <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
        <div style='font-size:12px;color:var(--muted)'>voices collected in small steps</div>
      </div>
    </div>
    <nav>
      <a href='index.html'>Root</a>
      <a href='about.html'>Philosophy</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Journeys</a>
      <a href='pricing.html'>Rates</a>
      <a href='testimonials.html' style='font-weight:600;color:var(--accent)'>Voices</a>
      <a href='book.html'>Reserve</a>
      <a href='contact.html'>Reach</a>
    </nav>
  </header>

  <main>
    <section style='padding:0 24px 22px 24px'>
      <h1 style='margin:6px 0 10px 0'>Stories from the pathways</h1>
      <p class='micro'>Clients share practical notes — habits kept, frameworks adopted, and small wins that stayed.</p>
    </section>

    <section class='grid'>
      <div>
        <div class='card'>
          <div class='testimonial'>
            <p class='quote'>"I used to overcomplicate mornings until we made three tiny choices. Now the day feels readable."</p>
            <div class='who'>— Lena, remote teacher</div>
            <div class='meta'><span class='rating'>★★★★☆</span><span class='micro'>Began with a 14-day micro-framework, now on a Steady Course</span></div>
          </div>
        </div>

        <div class='card'>
          <div class='testimonial'>
            <p class='quote'>"The habit checklist is my anchor. I can see what I did, and that matters more than perfection."</p>
            <div class='who'>— Marcus, startup founder</div>
            <div class='meta'><span class='rating'>★★★★★</span><span class='micro'>Hybrid Pathway participant</span></div>
          </div>
        </div>

        <div class='card'>
          <div class='testimonial'>
            <p class='quote'>"We built a custom plan for my irregular schedule — it's gentle, practical, and it fits."</p>
            <div class='who'>— Priya, nurse</div>
            <div class='meta'><span class='rating'>★★★★☆</span><span class='micro'>Starter Sprint to Steady Course transition</span></div>
          </div>
        </div>
      </div>

      <aside>
        <div class='card'>
          <h3 style='margin:0 0 8px 0'>Share your note</h3>
          <p class='micro'>Submit a short reflection and optionally request a follow-up.</p>
          <form onsubmit='event.preventDefault(); alert("Thanks — we'll be in touch at {{EMAIL}}")'>
            <input type='text' name='name' placeholder='Your name' style='width:100%;padding:8px;border-radius:8px;border:1px solid #e7efe8;margin-bottom:8px'>
            <textarea name='note' placeholder='A short note (1-2 lines)' style='width:100%;padding:8px;border-radius:8px;border:1px solid #e7efe8;height:80px'></textarea>
            <div style='display:flex;gap:8px;margin-top:8px'>
              <button class='btn btn-primary' type='submit'>Send note</button>
              <a class='btn' href='book.html' style='text-decoration:none'>Schedule a brief call</a>
            </div>
          </form>
          <p class='micro' style='margin-top:8px'>We welcome anonymized stories. No medical claims — just lived experience and practical habit work.</p>
        </div>

        <div class='card' style='margin-top:14px'>
          <h4 style='margin:0 0 8px 0'>Mini 7-Day — make a quick checklist</h4>
          <div class='mini-habit'>
            <input id='miniHabitName' placeholder='e.g., Evening wind-down'>
            <div style='display:flex;gap:8px;margin-top:8px'>
              <button class='btn btn-primary' id='miniMake'>Create</button>
              <button class='btn' id='miniPrint'>Print</button>
            </div>
          </div>
          <div id='miniOutput' style='margin-top:10px'></div>
        </div>

        <div class='card' style='margin-top:14px'>
          <h4 style='margin:0 0 8px 0'>Connect</h4>
          <p class='micro'>Prefer to speak? Call <strong>{{PHONE}}</strong> or email <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></p>
          <div style='margin-top:8px'><a href='book.html' class='btn btn-primary' style='text-decoration:none'>Reserve a slot</a></div>
        </div>
      </aside>
    </section>
  </main>

  <script>
    // Mini habit on testimonials
    function miniGenerate(name){
      if(!name) name = 'Practice';
      const lines = [];
      for(let i=1;i<=7;i++) lines.push('Day '+i+': '+name+' — check when done');
      return lines.join('\n');
    }
    document.getElementById('miniMake').addEventListener('click', ()=>{
      const name = document.getElementById('miniHabitName').value.trim();
      const out = miniGenerate(name);
      const o = document.getElementById('miniOutput'); o.textContent = out.replace(/\n/g,'\n');
      o.style.whiteSpace='pre-wrap';
    });
    document.getElementById('miniPrint').addEventListener('click', ()=>{
      const content = document.getElementById('miniOutput').textContent;
      if(!content){ alert('Create the checklist first'); return; }
      const w = window.open('','_blank','width=600,height=800');
      w.document.write('<pre style="font-family:Arial;padding:20px">'+content+'</pre>');
      w.document.close(); w.print();
    });
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Reserve a Session — Book</title>
  <style>
    :root{--bg:#f7fff9;--accent:#5a9c7a;--muted:#65766a;font-family:Inter,system-ui,Segoe UI,Roboto,Arial}
    body{margin:0;background:var(--bg);color:#0b1a14}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 22px}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    main{padding:20px}
    .wrap{max-width:980px;margin:0 auto;display:grid;grid-template-columns:1fr 360px;gap:22px}
    .card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(8,12,10,0.06)}
    .session-planner label{display:block;margin-top:8px;font-size:13px;color:var(--muted)}
    .input,textarea,select{width:100%;padding:10px;border-radius:8px;border:1px solid #e6efe8;margin-top:6px}
    .actions{display:flex;gap:10px;margin-top:12px}
    .btn{padding:9px 12px;border-radius:8px;border:0;cursor:pointer}
    .btn-primary{background:var(--accent);color:#fff}
    .summary{white-space:pre-wrap;background:#f4fff8;padding:12px;border-radius:8px;margin-top:10px;border:1px solid #eaf7ee}
    .note{font-size:13px;color:var(--muted);margin-top:8px}
    @media(max-width:880px){.wrap{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style='display:flex;gap:10px;align-items:center'>
      <div style='width:40px;height:40px;background:var(--accent);border-radius:8px;display:grid;place-items:center;color:#fff;font-weight:700'>W</div>
      <div>
        <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
        <div style='font-size:12px;color:var(--muted)'>Reserve a thoughtful session</div>
      </div>
    </div>
    <nav>
      <a href='index.html'>Root</a>
      <a href='about.html'>Philosophy</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Journeys</a>
      <a href='pricing.html'>Rates</a>
      <a href='testimonials.html'>Voices</a>
      <a href='book.html' style='font-weight:600;color:var(--accent)'>Reserve</a>
      <a href='contact.html'>Reach</a>
    </nav>
  </header>

  <main>
    <div class='wrap'>
      <section class='card'>
        <h2 style='margin:0 0 6px 0'>Session Planner</h2>
        <p class='note'>Build a compact plan for our time together. Use the planner to frame outcomes, select a framework, and export a plaintext summary you can copy into a calendar or email.</p>

        <div class='session-planner'>
          <label>Preferred focus area</label>
          <select id='focus' class='input'>
            <option value='clarity'>Clarity & Priorities</option>
            <option value='energy'>Energy & Sleep</option>
            <option value='boundaries'>Boundaries & Time</option>
            <option value='habit'>Daily Habit Architecture</option>
          </select>

          <label>Primary outcome you'd like</label>
          <input id='outcome' class='input' placeholder='One concise outcome (e.g., sleep 7hrs average)'>

          <label>Preferred session length</label>
          <select id='length' class='input'>
            <option value='30'>30 minutes</option>
            <option value='45'>45 minutes</option>
            <option value='60' selected>60 minutes</option>
          </select>

          <label>Preferred rhythm</label>
          <select id='rhythm' class='input'>
            <option value='once'>Single session</option>
            <option value='weekly'>Weekly check-ins</option>
            <option value='monthly'>Monthly reflection</option>
            <option value='hybrid'>Hybrid pathway</option>
          </select>

          <label>Choose an approach</label>
          <select id='approach' class='input'>
            <option value='mini'>Mini-framework: intention + cue + tiny action</option>
            <option value='map'>Map & milestones: weekly markers</option>
            <option value='habit-arch'>Habit architecture: build systems</option>
            <option value='experiment'>Experiment loop: test, measure, adapt</option>
          </select>

          <label>Anything to share before we meet?</label>
          <textarea id='notes' class='input' rows='4' placeholder='Context, constraints, schedule notes'></textarea>

          <div class='actions'>
            <button class='btn btn-primary' id='compose'>Compose summary</button>
            <button class='btn' id='copyBtn'>Copy</button>
            <button class='btn' id='emailBtn'>Email me a copy</button>
            <button class='btn' id='bookNow' onclick="location.href='contact.html'">Proceed to booking</button>
          </div>

          <div id='planSummary' class='summary' aria-live='polite'>A short plan will appear here when you compose.</div>
        </div>
      </section>

      <aside class='card'>
        <h3 style='margin:0 0 8px 0'>Reserve details</h3>
        <form id='bookingForm' onsubmit='event.preventDefault(); alert("Thanks — a confirmation will be sent to {{EMAIL}} (demo)")'>
          <label style='font-size:13px;color:var(--muted)'>Your name</label>
          <input class='input' name='name' required>
          <label style='font-size:13px;color:var(--muted)'>Email</label>
          <input class='input' name='email' required placeholder='you@example.com'>
          <label style='font-size:13px;color:var(--muted)'>Phone</label>
          <input class='input' name='phone' placeholder='Optional'>

          <label style='font-size:13px;color:var(--muted)'>Choose a plan</label>
          <select name='plan' class='input'>
            <option>Starter Sprint — 4 weeks</option>
            <option>Steady Course — 12 weeks</option>
            <option>Hybrid Pathway — 6 months</option>
          </select>

          <label style='font-size:13px;color:var(--muted)'>Preferred date</label>
          <input type='date' name='date' class='input'>

          <div style='margin-top:12px;display:flex;gap:8px'>
            <button class='btn btn-primary' type='submit'>Confirm request</button>
            <button class='btn' type='button' onclick="location.href='pricing.html'">See rates</button>
          </div>
        </form>

        <p class='note'>If you'd like a phone conversation first call <strong>{{PHONE}}</strong>. We will follow up to arrange times. Billing and refunds outlined on the confirmation.</p>
      </aside>
    </div>
  </main>

  <script>
    // Session Planner logic
    function readInputs(){
      return {
        focus: document.getElementById('focus').value,
        outcome: document.getElementById('outcome').value.trim(),
        length: document.getElementById('length').value,
        rhythm: document.getElementById('rhythm').value,
        approach: document.getElementById('approach').value,
        notes: document.getElementById('notes').value.trim()
      };
    }

    function buildPlan(data){
      const lines = [];
      lines.push('Session Planner — {{BUSINESS_NAME}}');
      lines.push('Focus: '+data.focus);
      if(data.outcome) lines.push('Desired outcome: '+data.outcome);
      lines.push('Length: '+data.length+' minutes');
      lines.push('Rhythm: '+data.rhythm);
      lines.push('Approach: '+data.approach);
      lines.push('Suggested starter steps:');

      // small logic for starter steps
      if(data.approach === 'mini'){
        lines.push('- Clarify one habit cue and one tiny action (2 min)');
        lines.push('- Agree on a daily check-in prompt');
      } else if(data.approach === 'map'){
        lines.push('- Set 3 milestones over the chosen rhythm');
        lines.push('- Decide on what you will track each week');
      } else if(data.approach === 'habit-arch'){
        lines.push('- Choose a keystone habit and an anchor routine');
        lines.push('- Build a 7-day micro-challenge to begin')
      } else {
        lines.push('- Frame an experiment: 1 variable to change, 1 metric to track');
      }

      if(data.notes) {
        lines.push('Context notes:');
        lines.push(data.notes);
      }

      lines.push('Next steps: Book a time at '+ (data.rhythm === 'once' ? 'single session' : (data.rhythm === 'weekly' ? 'weekly check-ins' : 'a rhythm that fits you')));
      lines.push('\n— End of plan —');
      return lines.join('\n');
    }

    document.getElementById('compose').addEventListener('click', ()=>{
      const data = readInputs();
      const summary = buildPlan(data);
      document.getElementById('planSummary').textContent = summary;
    });

    document.getElementById('copyBtn').addEventListener('click', async ()=>{
      const text = document.getElementById('planSummary').textContent.trim();
      if(!text){ alert('Compose a summary first'); return; }
      try{
        await navigator.clipboard.writeText(text);
        alert('Plan copied to clipboard');
      }catch(e){
        // fallback
        const ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); try{document.execCommand('copy'); alert('Plan copied');}catch(err){alert('Copy failed');} ta.remove();
      }
    });

    document.getElementById('emailBtn').addEventListener('click', ()=>{
      const text = encodeURIComponent(document.getElementById('planSummary').textContent || '');
      if(!text){ alert('Compose a summary first'); return; }
      const mailto = 'mailto:{{EMAIL}}?subject='+encodeURIComponent('Session plan request')+'&body='+text;
      window.location.href = mailto;
    });
  </script>
</body>
